```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "An OWL ontology modelling securities, debt/equity/hybrid instruments, derivatives, investment funds, issuers and investors, as described in the supplied corpus." .

#################################################################
# 1. TOP-LEVEL FINANCIAL INSTRUMENT HIERARCHY
#################################################################

fis:FinancialInstrument a owl:Class ;
  rdfs:label "financial instrument" ;
  rdfs:comment "A monetary contract between parties, which can be created, traded, modified and settled. Per IAS 32: any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity." .

fis:Asset a owl:Class ;
  rdfs:label "asset" ;
  rdfs:comment "A resource, including a financial instrument, commodity, currency, interest rate or index, that can serve as the underlier or collateral of another instrument." .

fis:FinancialInstrument rdfs:subClassOf fis:Asset .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "cash instrument" ;
  rdfs:comment "An instrument whose value is determined directly by the markets; includes securities (readily transferable) and non-negotiable instruments such as loans and deposits." .

fis:Derivative a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "derivative" , "derivative instrument" ;
  rdfs:comment "A contract between a buyer and seller whose value depends on the performance of an underlier (commodity, financial instrument, index, currency or interest rate). CONFLICT NOTE: the corpus states in one passage that derivatives are a sub-category of securities (US SEC view: debt, equity, derivatives), while elsewhere derivatives are described as one of three main categories of financial instruments alongside equity and debt (implying they are not securities). This ontology follows the majority treatment, modelling Derivative as a FinancialInstrument that is not a subclass of Security." .

fis:NonNegotiableCashInstrument a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "non-negotiable cash instrument" ;
  rdfs:comment "Cash instruments such as loans and deposits where both borrower and lender must agree on a transfer; not readily transferable like securities." .

fis:Security a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "security" ;
  rdfs:comment "A tradable financial asset; a financial contract which entitles the holder to investment returns, enforceable by law. Legal definitions vary by jurisdiction." .

owl:AllDisjointClasses [ owl:members ( fis:Security fis:NonNegotiableCashInstrument ) ] .

#################################################################
# 2. SECURITY HIERARCHY: DEBT, EQUITY, HYBRID
#################################################################

fis:DebtSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "debt security" ;
  rdfs:comment "A security under which the holder is entitled to payment of principal and interest; the issuer (debtor) owes the holder (creditor) a debt. May be called debentures, bonds, deposits, notes or commercial paper depending on maturity, collateral and other characteristics." .

fis:EquitySecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "equity security" , "stock" , "share" ;
  rdfs:comment "A share of equity interest in an entity such as the capital stock of a company, trust or partnership; entitles the holder (shareholder) to a pro rata portion of control, profits and capital gain, and to a residual claim in bankruptcy." .

fis:HybridSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "hybrid security" ;
  rdfs:comment "A security combining some of the characteristics of both debt and equity securities, e.g. preference shares, convertibles and equity warrants. Not disjoint with DebtSecurity/EquitySecurity since it deliberately straddles both." .

owl:AllDisjointClasses [ owl:members ( fis:DebtSecurity fis:EquitySecurity ) ] .

#################################################################
# 3. ISSUER AND INVESTOR HIERARCHIES
#################################################################

fis:Issuer a owl:Class ;
  rdfs:label "issuer" ;
  rdfs:comment "The company or other entity issuing a security." .

fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:label "corporation" ;
  rdfs:comment "A commercial or industrial entity that may issue corporate bonds and equity securities." .

fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:label "sovereign government" ;
  rdfs:comment "A national government that issues sovereign/government bonds." .

fis:LocalGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:label "local government" , "sub-sovereign government" ;
  rdfs:comment "State, provincial, territorial, municipal or other governmental unit other than a sovereign government." .

fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:label "supranational organization" ;
  rdfs:comment "An international organization such as the World Bank, IMF or a regional multilateral development bank." .

owl:AllDisjointClasses [ owl:members ( fis:Corporation fis:SovereignGovernment fis:LocalGovernment fis:SupranationalOrganization ) ] .

fis:Investor a owl:Class ;
  rdfs:label "investor" ;
  rdfs:comment "A person or institution that holds securities." .

fis:RetailInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:label "retail investor" ;
  rdfs:comment "A member of the public investing personally, other than by way of business." .

fis:InstitutionalInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:label "institutional investor" , "wholesale investor" ;
  rdfs:comment "A financial institution acting on its own account or on behalf of clients, e.g. investment banks, insurance companies, pension funds." .

owl:AllDisjointClasses [ owl:members ( fis:RetailInvestor fis:InstitutionalInvestor ) ] .

fis:Shareholder a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:label "shareholder" , "stockholder" ;
  rdfs:comment "An individual or company that legally owns one or more shares of stock." .

fis:Bondholder a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:label "bondholder" ;
  rdfs:comment "The creditor holding a bond; entitled to interest and principal repayment." .

#################################################################
# 4. UNDERLYING ASSET / COLLATERAL HIERARCHY
#################################################################

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:label "commodity" .

fis:Currency a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:label "currency" .

fis:InterestRate a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:label "interest rate" .

fis:MarketIndex a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:label "market index" , "price index" .

fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:label "mortgage" .

fis:DebtObligation a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:label "debt obligation" ;
  rdfs:comment "A loan, receivable or other debt obligation (e.g. consumer loans, leases, receivables) used as collateral for asset-backed securities." .

#################################################################
# 5. DEBT SECURITY / BOND HIERARCHY
#################################################################

fis:Bond a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "bond" ;
  rdfs:comment "A debt security under which the issuer owes the holder a debt and is obliged to repay the principal at the maturity date plus interest (the coupon) over time; generally issued for a term of one year or more." .

fis:MoneyMarketInstrument a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "money market instrument" ;
  rdfs:comment "A short-term debt instrument with original maturity of one year or less; generally designated a money market instrument rather than a bond." .

owl:AllDisjointClasses [ owl:members ( fis:Bond fis:MoneyMarketInstrument ) ] .

fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:label "commercial paper" ;
  rdfs:comment "An unsecured promissory note with a fixed maturity of usually less than 270 days, sold at a discount from face value." .

fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:label "certificate of deposit" ;
  rdfs:comment "A time deposit with a specific, fixed term before money can be withdrawn without penalty, commonly offered by banks, thrift institutions and credit unions." .

fis:TreasuryBill a owl:Class ;
  rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:label "treasury bill" ;
  rdfs:comment "Short-term debt obligations of a national government maturing in three to twelve months, issued at a discount. CORPUS CONFLICT: elsewhere described as 'zero-coupon bonds that mature in one year or less', suggesting bond-like status; modelled here as a MoneyMarketInstrument per the majority maturity-based classification." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:MoneyMarketInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
      [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "zero" ]
    )
  ] .

# --- Bonds classified by issuer ---

fis:GovernmentBond a owl:Class ;
  rdfs:label "government bond" , "sovereign bond" , "treasury bond" ;
  rdfs:comment "A bond issued by a sovereign national government to support public spending." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
    )
  ] .

fis:CorporateBond a owl:Class ;
  rdfs:label "corporate bond" ;
  rdfs:comment "A bond issued by a corporation to raise financing, e.g. to fund operations, mergers and acquisitions, or expansion." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
    )
  ] .

fis:MunicipalBond a owl:Class ;
  rdfs:label "municipal bond" , "sub-sovereign government bond" ;
  rdfs:comment "A bond issued by state or local governments, or entities they create such as authorities and special districts." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ]
    )
  ] .

fis:SupranationalBond a owl:Class ;
  rdfs:label "supranational bond" ;
  rdfs:comment "A bond issued by a supranational organisation such as the World Bank." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ]
    )
  ] .

owl:AllDisjointClasses [ owl:members ( fis:GovernmentBond fis:CorporateBond fis:MunicipalBond fis:SupranationalBond ) ] .

fis:TreasuryNote a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:label "treasury note" ;
  rdfs:comment "US government bond with a maturity of two, three, five or ten years." .

fis:TreasuryBondUS a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:label "treasury bond (US)" ;
  rdfs:comment "US government bond (T-bond) with the longest maturity, from twenty to thirty years." .

owl:AllDisjointClasses [ owl:members ( fis:TreasuryBill fis:TreasuryNote fis:TreasuryBondUS ) ] .

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:label "war bond" ;
  rdfs:comment "A bond issued by a government to fund military operations and expenditure during wartime." .

fis:GeneralObligationBond a owl:Class ;
  rdfs:subClassOf fis:MunicipalBond ;
  rdfs:label "general obligation bond" ;
  rdfs:comment "Principal and interest are secured by the full faith and credit of the issuer, usually supported by its taxing power." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:MunicipalBond
      [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:hasValue "taxingPower" ]
    )
  ] .

fis:RevenueBond a owl:Class ;
  rdfs:subClassOf fis:MunicipalBond ;
  rdfs:label "revenue bond" ;
  rdfs:comment "Promises to repay principal and interest solely from a specified stream of future income; typically non-recourse." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:MunicipalBond
      [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:hasValue "revenueStream" ]
    )
  ] .

fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond ;
  rdfs:label "assessment bond" ;
  rdfs:comment "Promises repayment based on property tax assessments of properties within the issuer's boundaries; treated as a form of general obligation bond." .

owl:AllDisjointClasses [ owl:members ( fis:GeneralObligationBond fis:RevenueBond ) ] .

# --- Bonds classified by coupon structure ---

fis:FixedRateBond a owl:Class ;
  rdfs:label "fixed rate bond" ;
  rdfs:comment "A bond whose coupon remains constant throughout its life." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "fixed" ]
    )
  ] .

fis:FloatingRateNote a owl:Class ;
  rdfs:label "floating rate note" ;
  rdfs:comment "A bond (floater) whose coupon varies over its life based on a money-market reference rate." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "floating" ]
    )
  ] .

fis:ZeroCouponBond a owl:Class ;
  rdfs:label "zero-coupon bond" , "discount bond" ;
  rdfs:comment "A bond that pays no regular interest; issued at a substantial discount to par, with the holder receiving the full principal at maturity." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "zero" ]
    )
  ] .

owl:AllDisjointClasses [ owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) ] .

fis:PerpetualBond a owl:Class ;
  rdfs:label "perpetual bond" , "perpetuity" ;
  rdfs:comment "A bond with no maturity date; principal is repaid only at the discretion of the borrower, if at all." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:isPerpetual ; owl:hasValue true ]
    )
  ] .

# --- Bonds classified by embedded option ---

fis:CallableBond a owl:Class ;
  rdfs:label "callable bond" ;
  rdfs:comment "A bond giving the issuer the right to repay the bond before the maturity date on the call dates." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCallProvision ; owl:hasValue true ]
    )
  ] .

fis:PutableBond a owl:Class ;
  rdfs:label "putable bond" , "retractable bond" ;
  rdfs:comment "A bond giving the holder the right to force the issuer to repay the bond before the maturity date on the put dates." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasPutProvision ; owl:hasValue true ]
    )
  ] .

fis:ConvertibleBond a owl:Class ;
  rdfs:subClassOf fis:HybridSecurity ;
  rdfs:label "convertible bond" , "convertible note" , "convertible debenture" ;
  rdfs:comment "A bond that the holder can convert into a specified number of shares of common stock in the issuing company, or cash of equal value; a hybrid security with debt and equity features." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:EquitySecurity ]
    )
  ] .

fis:BulletBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "bullet bond" ;
  rdfs:comment "A straight bond that is neither callable nor putable." .

# --- Bonds classified by seniority / credit quality ---

fis:SeniorBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "senior bond" ;
  rdfs:comment "Debt contractually senior to other unsecured debt, giving holders priority in a bankruptcy of the issuer." .

fis:SubordinatedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "subordinated bond" ;
  rdfs:comment "A bond with lower priority than other bonds of the issuer in case of liquidation; debt that is not senior." .

owl:AllDisjointClasses [ owl:members ( fis:SeniorBond fis:SubordinatedBond ) ] .

fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "high-yield bond" , "junk bond" ;
  rdfs:comment "A bond rated below investment grade by credit rating agencies, carrying higher default risk and higher yield." .

fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "investment-grade bond" , "high-grade bond" ;
  rdfs:comment "A bond rated AAA, AA, A or BBB." .

owl:AllDisjointClasses [ owl:members ( fis:HighYieldBond fis:InvestmentGradeBond ) ] .

# --- Bonds classified by certificate form ---

fis:BearerBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "bearer bond" ;
  rdfs:comment "An official certificate issued without a named holder; the person possessing the paper certificate can claim the value of the bond." .

fis:RegisteredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "registered bond" ;
  rdfs:comment "A bond whose ownership is recorded by the issuer or a transfer agent; interest and principal are sent to the registered owner." .

fis:BookEntryBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "book-entry bond" ;
  rdfs:comment "A bond that does not have a paper certificate." .

owl:AllDisjointClasses [ owl:members ( fis:BearerBond fis:RegisteredBond fis:BookEntryBond ) ] .

# --- Asset-backed family ---

fis:AssetBackedSecurity a owl:Class ;
  rdfs:label "asset-backed security" ;
  rdfs:comment "A bond whose interest and principal payments are backed by underlying cash flows from a pool of other assets (e.g. consumer loans, receivables)." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:DebtSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Asset ]
    )
  ] .
fis:AssetBackedSecurity rdfs:subClassOf fis:Bond .

fis:MortgageBackedSecurity a owl:Class ;
  rdfs:label "mortgage-backed security" ;
  rdfs:comment "An asset-backed security secured by a mortgage or a pool of mortgages." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ]
    )
  ] .

fis:CollateralizedDebtObligation a owl:Class ;
  rdfs:label "collateralized debt obligation" ;
  rdfs:comment "A type of structured asset-backed security backed by a pool of bonds or other debt obligations, sliced into tranches by seniority." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:DebtObligation ]
    )
  ] .

fis:ResidentialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "residential mortgage-backed security" ;
  rdfs:comment "An MBS secured by single-family, one- to four-unit real estate." .

fis:CommercialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "commercial mortgage-backed security" ;
  rdfs:comment "An MBS secured by commercial and multi-family properties." .

owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) ] .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "covered bond" ;
  rdfs:comment "A bond backed by cash flows from mortgages or public-sector assets; unlike asset-backed securities, the assets remain on the issuer's balance sheet." .

owl:AllDisjointClasses [ owl:members ( fis:CoveredBond fis:AssetBackedSecurity ) ] .

fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "climate bond" , "green bond" ;
  rdfs:comment "A bond issued by a government or corporate entity to raise finance for climate change mitigation or adaptation projects." .

fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "social impact bond" ;
  rdfs:comment "An agreement for public-sector entities to repay private investors after meeting verified improved social outcome goals." .

#################################################################
# 6. EQUITY SECURITY HIERARCHY
#################################################################

fis:CommonStock a owl:Class ;
  rdfs:subClassOf fis:EquitySecurity ;
  rdfs:label "common stock" , "ordinary share" , "voting share" , "equity share" ;
  rdfs:comment "A unit of ownership that typically carries voting rights and lowest priority to receive pay-outs from the company." .

fis:PreferredStock a owl:Class ;
  rdfs:subClassOf fis:EquitySecurity , fis:HybridSecurity ;
  rdfs:label "preferred stock" , "preference share" , "preferred share" ;
  rdfs:comment "A component of share capital senior to common stock but subordinate to bonds, combining properties of debt and equity; generally no voting rights, but priority in dividends and liquidation." .

owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:CumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:label "cumulative preferred stock" ;
  rdfs:comment "Preferred stock requiring that unpaid or reduced dividends accumulate and be made up before common dividends resume." .

fis:NoncumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:label "noncumulative preferred stock" , "straight preferred stock" ;
  rdfs:comment "Preferred stock for which any passed dividend is simply lost, not accumulated." .

owl:AllDisjointClasses [ owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) ] .

fis:ConvertiblePreferredStock a owl:Class ;
  rdfs:subClassOf fis:PreferredStock ;
  rdfs:label "convertible preferred stock" , "convertible preference share" ;
  rdfs:comment "Preferred stock that includes the ability of the holder to convert the preferred shares into a fixed number of common shares." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:PreferredStock
      [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ]
    )
  ] .

fis:DepositaryReceipt a owl:Class ;
  rdfs:subClassOf fis:EquitySecurity ;
  rdfs:label "depositary receipt" ;
  rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities, trading on a local exchange." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:EquitySecurity
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ]
    )
  ] .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:label "American depositary receipt" ;
  rdfs:comment "A depositary receipt listed and traded in the United States." .

fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:label "European depositary receipt" .

fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:label "global depositary receipt" .

owl:AllDisjointClasses [ owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) ] .

#################################################################
# 7. HYBRID SECURITY HIERARCHY (NON-STOCK, NON-BOND)
#################################################################

fis:EquityWarrant a owl:Class ;
  rdfs:subClassOf fis:HybridSecurity ;
  rdfs:label "equity warrant" , "warrant" ;
  rdfs:comment "An option issued by a company allowing the holder to purchase a specific number of shares at a specified price within a specified time; often issued with bonds or existing equities and separately tradeable." .

#################################################################
# 8. DERIVATIVE HIERARCHY
#################################################################

fis:Forward a owl:Class ;
  rdfs:subClassOf fis:Derivative ;
  rdfs:label "forward" , "forward contract" ;
  rdfs:comment "A non-standardized, over-the-counter contract between two parties to buy or sell an asset at a specified future time at a price agreed today." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue false ]
    )
  ] .

fis:Future a owl:Class ;
  rdfs:subClassOf fis:Derivative ;
  rdfs:label "future" , "futures contract" ;
  rdfs:comment "A standardized contract, written by a clearing house that operates an exchange, to buy or sell an asset at a price agreed today, with delivery and payment at a specified future date." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue true ]
    )
  ] .

owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future ) ] .

fis:Option a owl:Class ;
  rdfs:subClassOf fis:Derivative ;
  rdfs:label "option" ;
  rdfs:comment "A contract giving the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

fis:CallOption a owl:Class ;
  rdfs:label "call option" ;
  rdfs:comment "An option that conveys to the owner the right to buy an asset at a specified price." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasOptionRight ; owl:hasValue "buy" ]
    )
  ] .

fis:PutOption a owl:Class ;
  rdfs:label "put option" ;
  rdfs:comment "An option that conveys to the owner the right to sell an asset at a specified price." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasOptionRight ; owl:hasValue "sell" ]
    )
  ] .

owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanOption a owl:Class ;
  rdfs:label "American option" ;
  rdfs:comment "An option that may be exercised on any trading day on or before expiration." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "American" ]
    )
  ] .

fis:EuropeanOption a owl:Class ;
  rdfs:label "European option" ;
  rdfs:comment "An option that may only be exercised on the expiration date." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "European" ]
    )
  ] .

owl:AllDisjointClasses [ owl:members ( fis:AmericanOption fis:EuropeanOption ) ] .

fis:Warrant a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:label "long-dated option" ;
  rdfs:comment "A long-dated option, generally traded over the counter, distinguished from commonly used short-dated options." .

fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:label "binary option" ;
  rdfs:comment "An all-or-nothing option that pays the full amount if the underlying meets the defined condition at expiration, otherwise nothing." .

fis:Swap a owl:Class ;
  rdfs:subClassOf fis:Derivative ;
  rdfs:label "swap" ;
  rdfs:comment "A derivative in which two counterparties exchange cash flows of one party's financial instrument for those of the other, based on a notional principal amount that is usually not exchanged." .

fis:InterestRateSwap a owl:Class ;
  rdfs:label "interest rate swap" ;
  rdfs:comment "A swap exchanging cash flows representing streams of periodic interest payments in one currency." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:InterestRate ]
    )
  ] .

fis:CurrencySwap a owl:Class ;
  rdfs:label "currency swap" , "cross-currency swap" ;
  rdfs:comment "A swap exchanging cash flows representing streams of periodic interest payments in two different currencies." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Currency ]
    )
  ] .

fis:CreditDefaultSwap a owl:Class ;
  rdfs:subClassOf fis:Swap ;
  rdfs:label "credit default swap" ;
  rdfs:comment "A swap in which the seller compensates the buyer in the event of a loan default or other credit event of a reference entity, in exchange for periodic premium payments." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:Issuer ]
    )
  ] .

owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap ) ] .

fis:StockDerivative a owl:Class ;
  rdfs:label "stock derivative" ;
  rdfs:comment "Any financial instrument for which the underlying asset is the price of an equity." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ]
    )
  ] .

owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future fis:Option fis:Swap ) ] .

#################################################################
# 9. INVESTMENT FUND HIERARCHY
#################################################################

fis:InvestmentFund a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "investment fund" , "fund" ;
  rdfs:comment "An investment vehicle that pools money from many investors and invests in stocks, bonds, money-market instruments or other securities; value is derived from the underlying portfolio of instruments it holds." .

fis:MutualFund a owl:Class ;
  rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "mutual fund" ;
  rdfs:comment "An open-end investment company whose shares are purchased from or redeemed to the issuer at the next calculated net asset value." .

fis:ExchangeTradedFund a owl:Class ;
  rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "exchange-traded fund" , "ETF" ;
  rdfs:comment "An exchange-traded investment product registered as an open-end investment company or unit investment trust, whose shares are bought and sold on exchanges at market prices that may differ from net asset value." .

owl:AllDisjointClasses [ owl:members ( fis:MutualFund fis:ExchangeTradedFund ) ] .

fis:IndexFund a owl:Class ;
  rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "index fund" ;
  rdfs:comment "A passively managed fund that tracks the performance of an index." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:InvestmentFund
      [ a owl:Restriction ; owl:onProperty fis:hasInvestmentStrategy ; owl:hasValue "passive" ]
    )
  ] .

fis:ActivelyManagedFund a owl:Class ;
  rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "actively managed fund" ;
  rdfs:comment "A fund that seeks to outperform market indices through active security selection." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:InvestmentFund
      [ a owl:Restriction ; owl:onProperty fis:hasInvestmentStrategy ; owl:hasValue "active" ]
    )
  ] .

owl:AllDisjointClasses [ owl:members ( fis:IndexFund fis:ActivelyManagedFund ) ] .

fis:MoneyMarketFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "money market fund" ;
  rdfs:comment "A fund that invests in liquid, short-term, high-quality debt securities." .

fis:BondFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "bond fund" , "fixed-income fund" .

fis:StockFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "stock fund" , "equity fund" .

owl:AllDisjointClasses [ owl:members ( fis:MoneyMarketFund fis:BondFund fis:StockFund ) ] .

#################################################################
# 10. DIVIDEND
#################################################################

fis:Dividend a owl:Class ;
  rdfs:label "dividend" ;
  rdfs:comment "A discretionary distribution of a portion of a company's profits to shareholders, declared by the board of directors; contrasted with the contractually fixed coupon on a bond." .

#################################################################
# 11. OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Security ;
  rdfs:range fis:Issuer ;
  rdfs:label "has issuer" ;
  rdfs:comment "Relates a security to the single entity that issues it." .

fis:isIssuerOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ;
  rdfs:range fis:Security ;
  rdfs:label "is issuer of" .

fis:hasUnderlying a owl:ObjectProperty ;
  rdfs:domain fis:Derivative ;
  rdfs:range fis:Asset ;
  rdfs:label "has underlying" ;
  rdfs:comment "Relates a derivative to the item (underlier) whose performance determines its value: a commodity, financial instrument, index, currency or interest rate." .

fis:isUnderlyingOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:Asset ;
  rdfs:range fis:Derivative ;
  rdfs:label "is underlying of" .

fis:hasCollateral a owl:ObjectProperty ;
  rdfs:domain fis:DebtSecurity ;
  rdfs:range fis:Asset ;
  rdfs:label "has collateral" ;
  rdfs:comment "Relates a debt security to the asset(s) backing its interest and principal payments." .

fis:isCollateralOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasCollateral ;
  rdfs:domain fis:Asset ;
  rdfs:range fis:DebtSecurity ;
  rdfs:label "is collateral of" .

fis:hasConversionTarget a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain fis:HybridSecurity ;
  rdfs:range fis:EquitySecurity ;
  rdfs:label "has conversion target" ;
  rdfs:comment "Relates a convertible security to the class of equity security into which it may be converted." .

fis:isConversionTargetOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasConversionTarget ;
  rdfs:domain fis:EquitySecurity ;
  rdfs:range fis:HybridSecurity ;
  rdfs:label "is conversion target of" .

fis:hasHolder a owl:ObjectProperty ;
  rdfs:domain fis:Security ;
  rdfs:range fis:Investor ;
  rdfs:label "has holder" ;
  rdfs:comment "Relates a security to an investor holding it." .

fis:isHolderOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasHolder ;
  rdfs:domain fis:Investor ;
  rdfs:range fis:Security ;
  rdfs:label "is holder of" .

fis:hasReferenceEntity a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain fis:CreditDefaultSwap ;
  rdfs:range fis:Issuer ;
  rdfs:label "has reference entity" ;
  rdfs:comment "Relates a credit default swap to the debt issuer whose creditworthiness backs the swap." .

fis:isReferenceEntityOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasReferenceEntity ;
  rdfs:domain fis:Issuer ;
  rdfs:range fis:CreditDefaultSwap ;
  rdfs:label "is reference entity of" .

fis:hasDividend a owl:ObjectProperty ;
  rdfs:domain fis:EquitySecurity ;
  rdfs:range fis:Dividend ;
  rdfs:label "has dividend" ;
  rdfs:comment "Relates an equity security to a dividend distribution declared on it." .

fis:isDividendOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasDividend ;
  rdfs:domain fis:Dividend ;
  rdfs:range fis:EquitySecurity ;
  rdfs:label "is dividend of" .

#################################################################
# 12. DATATYPE PROPERTIES
#################################################################

fis:hasFaceValue a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Security ;
  rdfs:range xsd:decimal ;
  rdfs:label "has face value" , "has par value" , "has nominal amount" ;
  rdfs:comment "The nominal, principal, par or face amount on which the issuer pays interest and which, most commonly, is repaid at the end of the term." .

fis:hasCouponRate a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:decimal ;
  rdfs:label "has coupon rate" ;
  rdfs:comment "The interest rate that the issuer pays to the bondholder." .

fis:hasCouponType a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:string ;
  rdfs:label "has coupon type" ;
  rdfs:comment "Classifies the bond's coupon structure as 'fixed', 'floating' or 'zero'." .

fis:hasMaturityDate a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ;
  rdfs:range xsd:date ;
  rdfs:label "has maturity date" ;
  rdfs:comment "The date on which the issuer is obligated to repay the nominal amount; after this date the issuer has no further obligations." .

fis:isPerpetual a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:boolean ;
  rdfs:label "is perpetual" ;
  rdfs:comment "True if the bond has no maturity date." .

fis:hasCallProvision a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:boolean ;
  rdfs:label "has call provision" ;
  rdfs:comment "True if the issuer has the right to repay the bond before maturity on call dates." .

fis:hasPutProvision a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Bond ;
  rdfs:range xsd:boolean ;
  rdfs:label "has put provision" ;
  rdfs:comment "True if the holder has the right to force early repayment on put dates." .

fis:hasRepaymentSource a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:MunicipalBond ;
  rdfs:range xsd:string ;
  rdfs:label "has repayment source" ;
  rdfs:comment "Classifies a municipal bond's source of repayment as 'taxingPower' (general obligation) or 'revenueStream' (revenue bond)." .

fis:hasCreditRating a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ;
  rdfs:range xsd:string ;
  rdfs:label "has credit rating" ;
  rdfs:comment "The grade assigned by a credit rating agency indicating the debt security's overall credit quality." .

fis:hasParValue a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:EquitySecurity ;
  rdfs:range xsd:decimal ;
  rdfs:label "has par value" ;
  rdfs:comment "A nominal accounting value used to represent equity on the balance sheet; some jurisdictions allow shares to be issued without par value." .

fis:hasDividendRate a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:PreferredStock ;
  rdfs:range xsd:decimal ;
  rdfs:label "has dividend rate" ;
  rdfs:comment "The negotiated, fixed-dividend amount of a preferred share, usually expressed as a percentage of par value." .

fis:hasDividendAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Dividend ;
  rdfs:range xsd:decimal ;
  rdfs:label "has dividend amount" .

fis:hasStrikePrice a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:decimal ;
  rdfs:label "has strike price" , "has exercise price" ;
  rdfs:comment "The fixed price at which the holder may buy or sell the underlying asset if the option is exercised." .

fis:hasPremium a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:decimal ;
  rdfs:label "has premium" ;
  rdfs:comment "The amount the option buyer pays the writer for the right conferred by the option." .

fis:hasExpirationDate a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ;
  rdfs:range xsd:date ;
  rdfs:label "has expiration date" ;
  rdfs:comment "The last date on which a derivative contract, such as an option, may be exercised." .

fis:hasOptionRight a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:string ;
  rdfs:label "has option right" ;
  rdfs:comment "Classifies an option as conferring the right to 'buy' (call) or 'sell' (put) the underlying." .

fis:hasExerciseStyle a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Option ;
  rdfs:range xsd:string ;
  rdfs:label "has exercise style" ;
  rdfs:comment "Classifies an option as 'American' (exercisable any time up to expiry) or 'European' (exercisable only at expiry)." .

fis:isStandardized a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ;
  rdfs:range xsd:boolean ;
  rdfs:label "is standardized" ;
  rdfs:comment "True if the derivative is a standardized, exchange-traded contract (e.g. a future); false if it is a non-standardized, bilaterally negotiated contract (e.g. a forward)." .

fis:hasNotionalAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Swap ;
  rdfs:range xsd:decimal ;
  rdfs:label "has notional amount" ;
  rdfs:comment "The nominal amount used to calculate payments on a swap; generally not exchanged between counterparties." .

fis:hasInvestmentStrategy a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:InvestmentFund ;
  rdfs:range xsd:string ;
  rdfs:label "has investment strategy" ;
  rdfs:comment "Classifies a fund's management approach as 'passive' (index-tracking) or 'active' (seeking to outperform an index)." .
