  rdfs:domain fis:PreferredStock ; rdfs:range xsd:boolean .
fis:isFungible a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:boolean .
fis:hasMeasurementCategory a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialAsset ; rdfs:range xsd:string .

#################################################################
#  UNDERLYING (for derivatives)
#################################################################

fis:Underlying a owl:Class ;
  rdfs:comment "An item (commodity, financial instrument, price index, currency or interest rate) that a derivative references." .
fis:Commodity a owl:Class ; rdfs:subClassOf fis:Underlying .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Underlying .
fis:InterestRateIndex a owl:Class ; rdfs:subClassOf fis:Underlying .
fis:PriceIndex a owl:Class ; rdfs:subClassOf fis:Underlying .
fis:FinancialInstrument rdfs:subClassOf fis:Underlying .

#################################################################
#  IAS 32 / IFRS 9 ACCOUNTING LAYER
#################################################################

fis:FinancialAsset a owl:Class ;
  rdfs:comment "IAS 32: cash; a contractual right to receive cash or another financial instrument; a contractual right to exchange financial instruments under potentially favourable conditions; or an equity instrument of another entity." .

fis:FinancialLiability a owl:Class ;
  rdfs:comment "IAS 32: a legal obligation to deliver cash or another financial instrument, or to exchange financial instruments under potentially unfavourable conditions." .

owl:AllDisjointClasses [ owl:members ( fis:FinancialAsset fis:FinancialLiability ) ] .

fis:Security rdfs:subClassOf fis:FinancialAsset .

fis:CompoundFinancialInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "An instrument that must be classified and presented with separate liability and equity components, e.g. a convertible bond." .

fis:AmortisedCostFinancialAsset owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:FinancialAsset
      [ a owl:Restriction ; owl:onProperty fis:hasMeasurementCategory ; owl:hasValue "amortisedCost" ] ) ] .
fis:FVOCIFinancialAsset owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:FinancialAsset
      [ a owl:Restriction ; owl:onProperty fis:hasMeasurementCategory ; owl:hasValue "FVOCI" ] ) ] .
fis:FVTPLFinancialAsset owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:FinancialAsset
      [ a owl:Restriction ; owl:onProperty fis:hasMeasurementCategory ; owl:hasValue "FVTPL" ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:AmortisedCostFinancialAsset fis:FVOCIFinancialAsset fis:FVTPLFinancialAsset ) ] .

#################################################################
#  COLLATERAL / POOLED ASSET CLASSES (for ABS/MBS/CDO)
#################################################################

fis:DebtObligation a owl:Class ; rdfs:subClassOf fis:FinancialAsset .
fis:Receivable a owl:Class ; rdfs:subClassOf fis:FinancialAsset .
fis:CreditCardReceivable a owl:Class ; rdfs:subClassOf fis:Receivable .
fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Loan .
fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:AutoLoan a owl:Class ; rdfs:subClassOf fis:Loan .
fis:StudentLoan a owl:Class ; rdfs:subClassOf fis:Loan .

owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgage fis:CommercialMortgage ) ] .

#################################################################
#  BOND
#################################################################

fis:Bond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
      fis:DebtSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:someValuesFrom xsd:date ]
      [ a owl:Restriction ; owl:onProperty fis:hasFaceValue ; owl:someValuesFrom xsd:decimal ]
    ) ] ;
  rdfs:comment "A security under which the issuer owes the holder a debt and is obliged to repay principal at maturity plus interest (coupon)." .

fis:MoneyMarketInstrument a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:comment "Short term debt instrument with original maturity of one year or less." .

fis:Bond owl:disjointWith fis:MoneyMarketInstrument .

### Issuer-based bond subclasses

fis:GovernmentBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
  rdfs:label "government bond" ; rdfs:comment "Also called treasury bond; backed by full faith and credit of a sovereign government." .

fis:MunicipalBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] ;
  rdfs:label "municipal bond" .

fis:SupranationalBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] .

fis:CorporateBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:GovernmentBond fis:MunicipalBond fis:SupranationalBond fis:CorporateBond ) ] .

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "Issued by a government to fund military operations during wartime." .

### Municipal bond subtypes

fis:GeneralObligationBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:MunicipalBond
      [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:hasValue "taxingPower" ] ) ] .
fis:RevenueBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:MunicipalBond
      [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:hasValue "revenue" ] ) ] ;
  rdfs:comment "Non-recourse; repaid solely from revenues of a specified revenue-generating entity." .
fis:AssessmentBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:MunicipalBond
      [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:hasValue "propertyAssessment" ] ) ] .
fis:BuildAmericaBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Taxable municipal bond authorised by the American Recovery and Reinvestment Act of 2009." .

owl:AllDisjointClasses [ owl:members ( fis:GeneralObligationBond fis:RevenueBond fis:AssessmentBond ) ] .

### Seniority

fis:SeniorBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:hasValue "senior" ] ) ] .
fis:SubordinatedBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:hasValue "subordinated" ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:SeniorBond fis:SubordinatedBond ) ] .

### Credit quality

fis:InvestmentGradeBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCreditRatingCategory ; owl:hasValue "investmentGrade" ] ) ] .
fis:HighYieldBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCreditRatingCategory ; owl:hasValue "highYield" ] ) ] ;
  rdfs:label "junk bond" .
owl:AllDisjointClasses [ owl:members ( fis:InvestmentGradeBond fis:HighYieldBond ) ] .

### Embedded options

fis:CallableBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:CallOption ] ) ] .
fis:PutableBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:PutOption ] ) ] ;
  rdfs:label "retractable bond" .
fis:BulletBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A straight bond that is neither callable nor putable." .

### Conversion

fis:ConvertibleBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:HybridSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
  rdfs:subClassOf fis:CompoundFinancialInstrument ;
  rdfs:comment "Also considered a debt security; lets the holder convert the bond into a fixed number of common shares." .
fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Allows exchange into shares of a corporation other than the issuer." .
fis:MandatoryConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Forces the holder to convert into shares at maturity." .
fis:ContingentConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:label "CoCo" ;
  rdfs:comment "Automatically converts into equity if a pre-specified trigger event occurs." .
fis:PackagedConvertible a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A straight bond and a call option/warrant wrapped together, separately tradeable." .
fis:SyntheticConvertibleBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issued by an investment bank to replicate a convertible payoff on a specific underlying equity, settled in cash." .

### Coupon structure

fis:ZeroCouponBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] ;
  rdfs:label "discount bond" .
fis:StripBond a owl:Class ; rdfs:subClassOf fis:ZeroCouponBond ;
  rdfs:comment "Created by separating coupons from the principal of a coupon bond (STRIPS)." .
fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon remains constant throughout the life of the bond." .
fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon is linked to a reference rate of interest and recalculated periodically." .
fis:InflationIndexedBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasPrincipalIndexation ; owl:someValuesFrom xsd:string ] ) ] ;
  rdfs:label "linker" .
fis:LotteryBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issuer redeems randomly selected individual bonds within the issue according to a schedule." .

owl:AllDisjointClasses [ owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) ] .

### Maturity category

fis:ShortTermBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityCategory ; owl:hasValue "short" ] ) ] .
fis:MediumTermBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityCategory ; owl:hasValue "medium" ] ) ] .
fis:LongTermBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityCategory ; owl:hasValue "long" ] ) ] .
fis:PerpetualBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityCategory ; owl:hasValue "perpetual" ] ) ] ;
  rdfs:label "perpetuity" ; rdfs:comment "Has no maturity date; principal repaid only at the discretion of the borrower, if at all." .
fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Matures in installments over a period of time." .

owl:AllDisjointClasses [ owl:members ( fis:ShortTermBond fis:MediumTermBond fis:LongTermBond fis:PerpetualBond ) ] .

### Holding form (applies to Security generally)

fis:BearerSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Entitles the holder to rights merely by holding the instrument; transferred by delivery." .
fis:RegisteredSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Entitles the holder to rights only if recorded on a security register." .
fis:BookEntrySecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Non-certificated, electronic/dematerialized form." .

owl:AllDisjointClasses [ owl:members ( fis:BearerSecurity fis:RegisteredSecurity fis:BookEntrySecurity ) ] .

fis:DividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Each instrument constitutes a separate asset/debt, legally distinct from other securities in the same issue." .
fis:UndividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "The entire issue makes up one single asset, with each security a fractional part of the whole." .
owl:AllDisjointClasses [ owl:members ( fis:DividedSecurity fis:UndividedSecurity ) ] .

fis:BearerBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] .
fis:RegisteredBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] .
fis:BookEntryBond owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BookEntrySecurity ) ] .

### UK gilts

fis:Gilt a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "UK government bond, managed by the UK Debt Management Office." .
fis:ConventionalGilt a owl:Class ; rdfs:subClassOf fis:Gilt ;
  rdfs:comment "Fixed interest rate and length." .
fis:IndexLinkedGilt a owl:Class ; rdfs:subClassOf fis:Gilt, fis:InflationIndexedBond .
owl:AllDisjointClasses [ owl:members ( fis:ConventionalGilt fis:IndexLinkedGilt ) ] .

### US Treasury securities

fis:TreasuryNote a owl:Class ; rdfs:subClassOf fis:GovernmentBond, fis:MediumTermBond ;
  rdfs:comment "US Treasury security, maturity of two, three, five or ten years." .
fis:TreasuryBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond, fis:LongTermBond ;
  rdfs:comment "Longest-maturity US Treasury security, twenty to thirty years." .
fis:TreasuryInflationProtectedSecurity a owl:Class ; rdfs:subClassOf fis:GovernmentBond, fis:InflationIndexedBond ;
  rdfs:label "TIPS" .
fis:TreasuryFloatingRateNote a owl:Class ; rdfs:subClassOf fis:GovernmentBond, fis:FloatingRateNote .
fis:TreasuryBill owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
  rdfs:comment "Zero-coupon short-term government debt maturing in one year or less. NOTE: the corpus elsewhere calls Treasury bills 'zero-coupon bonds', conflicting with the general rule that debt securities under one year are money-market instruments rather than bonds; the money-market classification is adopted here as the governing rule, per the majority statement." .

### Collateral/asset-backed family

fis:AssetBackedSecurity owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:FinancialAsset ] ) ] ;
  rdfs:label "ABS" ;
  rdfs:comment "Bond whose interest and principal payments are backed by underlying cash flows from a pool of other assets." .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Backed by cash flows from mortgages or public-sector assets which, unlike an ABS, remain on the issuer's balance sheet." .

fis:MortgageBackedSecurity owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] ) ] ;
  rdfs:label "MBS" .
fis:ResidentialMortgageBackedSecurity owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] ;
  rdfs:label "RMBS" .
fis:CommercialMortgageBackedSecurity owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CommercialMortgage ] ) ] ;
  rdfs:label "CMBS" .
owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) ] .

fis:PassThroughSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "Allocates cash flows from the underlying pool to holders on a pro-rata basis." .
fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "CMO" ; rdfs:label "pay-through bond" ;
  rdfs:comment "Debt obligation collateralized by the assets it owns; classified as debt for income tax purposes." .
fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "SMBS" .
fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ; rdfs:label "IO" .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ; rdfs:label "PO" .
owl:AllDisjointClasses [ owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) ] .

fis:CollateralizedDebtObligation owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:DebtObligation ] ) ] ;
  rdfs:label "CDO" .

fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Public sector entities pay back private investors after meeting verified improved social outcome goals." .
fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issued to raise finance for climate change mitigation or adaptation projects." .
fis:ForeignCurrencyBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Denominated in a currency other than the issuer's domestic currency, e.g. a samurai bond." .

#################################################################
#  MONEY MARKET INSTRUMENTS
#################################################################

fis:CommercialPaper owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:DebtSecurity fis:MoneyMarketInstrument ) ] ;
  rdfs:comment "Unsecured promissory note with a fixed maturity usually less than 270 days." .

fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:Deposit, fis:MoneyMarketInstrument ;
  rdfs:label "CD" ; rdfs:comment "Time deposit with a specific, fixed term before withdrawal without penalty." .

fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Short-term loan arranged by selling securities with an agreement to repurchase at a fixed price and date." .

fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:FederalFundsInstrument a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Interest-bearing deposits held by banks at the Federal Reserve, lent at the federal funds rate." .
fis:MunicipalNote a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Short-term note issued by municipalities in anticipation of tax receipts or other revenues." .

fis:EuroDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Issued internationally outside the domestic market in a denomination different from the issuer's domicile." .
fis:Eurobond a owl:Class ; rdfs:subClassOf fis:EuroDebtSecurity, fis:Bond ;
  rdfs:comment "Characteristically underwritten, unsecured, interest paid gross." .
fis:Euronote a owl:Class ; rdfs:subClassOf fis:EuroDebtSecurity, fis:MoneyMarketInstrument .
fis:EuroCommercialPaper a owl:Class ; rdfs:subClassOf fis:Euronote .
fis:EuroCertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:Euronote .

#################################################################
#  STOCK / SHARE
#################################################################

fis:Stock a owl:Class ;
  rdfs:subClassOf fis:EquitySecurity ;
  rdfs:label "share" ;
  rdfs:comment "Consists of the shares by which ownership of a corporation is divided; a unit of account for corporate equity (also called 'stock' or 'share')." .

fis:CommonStock owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Stock
      [ a owl:Restriction ; owl:onProperty fis:hasVotingRights ; owl:hasValue true ] ) ] ;
  rdfs:label "ordinary share" ;
  rdfs:comment "Typically carries voting rights; lowest priority on dividends and liquidation proceeds." .

fis:PreferredStock a owl:Class ;
  rdfs:subClassOf fis:Stock, fis:HybridSecurity ;
  rdfs:label "preference share" ;
  rdfs:comment "Intermediate class between equities and debt; priority over common stock on dividends and liquidation; typically no voting rights." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Stock
      [ a owl:Restriction ; owl:onProperty fis:hasDividendPriority ; owl:hasValue true ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:ConvertiblePreferredStock owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
      [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] .

fis:CumulativePreferredStock owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
      [ a owl:Restriction ; owl:onProperty fis:hasCumulativeDividend ; owl:hasValue true ] ) ] ;
  rdfs:comment "Unpaid dividends accumulate as dividends in arrears." .
fis:NoncumulativePreferredStock owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
      [ a owl:Restriction ; owl:onProperty fis:hasCumulativeDividend ; owl:hasValue false ] ) ] ;
  rdfs:label "straight preferred stock" .
owl:AllDisjointClasses [ owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) ] .

fis:MandatorilyRedeemablePreferredStock owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
      [ a owl:Restriction ; owl:onProperty fis:hasRedemptionObligation ; owl:hasValue true ] ) ] ;
  rdfs:comment "CONFLICT NOTE: commonly classified in markets as preferred equity, but IAS 32 classifies a mandatorily redeemable preference share as a financial liability (not equity) because the issuer has an unavoidable contractual obligation to deliver cash. This ontology retains the market classification (subclass of PreferredStock/EquitySecurity) while flagging the IAS 32 divergence here rather than asserting a contradictory FinancialLiability axiom." .

fis:RestrictedStock a owl:Class ; rdfs:subClassOf fis:Stock ;
  rdfs:label "Rule 144 stock" ;
  rdfs:comment "Acquired in unregistered form; subject to SEC Rule 144 resale restrictions." .

#################################################################
#  HYBRID SECURITIES / WARRANTS
#################################################################

fis:EquityWarrant owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Warrant
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:subClassOf fis:HybridSecurity ;
  rdfs:comment "Option issued by the company allowing the holder to purchase a specific number of shares at a specified price within a specified time." .

#################################################################
#  DEPOSITARY RECEIPTS
#################################################################

fis:DepositaryReceipt a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities." .
fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "ADR" .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "EDR" .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "GDR" .
owl:AllDisjointClasses [ owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) ] .

#################################################################
#  DERIVATIVES
#################################################################

fis:Forward owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue false ] ) ] ;
  rdfs:comment "Non-standardized, tailored contract between two parties; not exchange-traded." .

fis:Future owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue true ]
      [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ] ) ] ;
  rdfs:comment "Standardized contract written by a clearing house that operates an exchange where the contract can be bought and sold." .

owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future ) ] .

fis:Option a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Gives the owner the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

fis:CallOption owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "call" ] ) ] .
fis:PutOption owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "put" ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanOption owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "American" ] ) ] ;
  rdfs:comment "May be exercised on any trading day on or before expiration." .
fis:EuropeanOption owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "European" ] ) ] ;
  rdfs:comment "May only be exercised on expiry." .
fis:BermudanOption owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "Bermudan" ] ) ] ;
  rdfs:comment "May be exercised only on specified dates on or before expiration." .
owl:AllDisjointClasses [ owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) ] .

fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Payoff determined by the average underlying price over a preset time period." .
fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "The underlying price must pass a certain barrier before it can be exercised." .
fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "All-or-nothing profit profile." .
fis:ExoticOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Any option with complex financial structures beyond vanilla American/European options." .

fis:Warrant a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "A long-dated option, generally traded over the counter." .

fis:ExchangeTradedDerivative owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ] ) ] .
fis:OverTheCounterDerivative owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue false ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:ExchangeTradedDerivative fis:OverTheCounterDerivative ) ] .

fis:Swap a owl:Class ; rdfs:subClassOf fis:Derivative, fis:OverTheCounterDerivative ;
  rdfs:comment "Two counterparties exchange cash flows of one financial instrument for those of another, based on a notional principal amount." .

fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap ; rdfs:label "cross-currency swap" .
fis:CommoditySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:EquitySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CreditDefaultSwap owl:equivalentClass
  [ a owl:Class ; owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:Issuer ] ) ] ;
  rdfs:label "CDS" ;
  rdfs:comment "Seller compensates the buyer in the event of a loan default or other credit event of the reference entity." .

owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CommoditySwap fis:EquitySwap fis:CreditDefaultSwap ) ] .

#################################################################
#  FUNDS
#################################################################

fis:InvestmentFund a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Pools money from many investors to purchase securities; the combined holdings form the fund's portfolio." .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "SEC-registered open-end investment company; shares transact at next calculated net asset value (NAV)." .
fis:ExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "ETF" ;
  rdfs:comment "Shares are bought and sold on national securities exchanges at market prices, which may differ from NAV." .
fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Pools money from investors with fewer regulatory protections and more flexible, riskier strategies than mutual funds." .

owl:AllDisjointClasses [ owl:members ( fis:MutualFund fis:ExchangeTradedFund fis:HedgeFund ) ] .

fis:MoneyMarketFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:BondFund a owl:Class ; rdfs:subClassOf fis:MutualFund ; rdfs:label "income fund" .
fis:EquityFund a owl:Class ; rdfs:subClassOf fis:MutualFund ; rdfs:label "stock fund" .
fis:HybridFund a owl:Class ; rdfs:subClassOf fis:MutualFund ; rdfs:label "balanced fund" .
owl:AllDisjointClasses [ owl:members ( fis:MoneyMarketFund fis:BondFund fis:EquityFund fis:HybridFund ) ] .

fis:IndexFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
  rdfs:comment "Passively managed fund that tracks the performance of an index." .
fis:ActivelyManagedFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
  rdfs:comment "Seeks to outperform market indices; generally charges higher fees." .
owl:AllDisjointClasses [ owl:members ( fis:IndexFund fis:ActivelyManagedFund ) ] .

fis:StockETF a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund .
fis:BondETF a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund .
fis:CommodityETF a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund .
fis:CurrencyETF a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund .
fis:InverseExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund ;
  rdfs:label "IETF" ; rdfs:comment "Designed to move opposite to its benchmark." .
fis:LeveragedExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund ;
  rdfs:label "LETF" ; rdfs:comment "Seeks to amplify the benchmark's daily return." .

#################################################################
#  MARKETS / OFFERINGS
#################################################################

fis:Market a owl:Class ; rdfs:comment "A venue or mechanism where securities are bought and sold." .
fis:PrimaryMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "Market for new securities, in which the issuer receives the sale proceeds directly." .
fis:SecondaryMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "Market for already-issued securities; proceeds do not go to the original issuer." .
owl:AllDisjointClasses [ owl:members ( fis:PrimaryMarket fis:SecondaryMarket ) ] .

fis:SecurityOffering a owl:Class ;
  rdfs:comment "The process by which securities are offered to investors." .
fis:PublicOffering a owl:Class ; rdfs:subClassOf fis:SecurityOffering ;
  rdfs:comment "Securities offered to the public; publicly tradable thereafter." .
fis:PrivatePlacement a owl:Class ; rdfs:subClassOf fis:SecurityOffering ;
  rdfs:comment "Offered privately to a limited number of qualified persons; not publicly tradable." .
owl:AllDisjointClasses [ owl:members ( fis:PublicOffering fis:PrivatePlacement ) ] .

#################################################################
#  EXCHANGES (brief)
#################################################################

fis:Exchange a owl:Class ; rdfs:comment "An organized and officially recognized market on which securities can be bought and sold." .
fis:StockExchange a owl:Class ; rdfs:subClassOf fis:Exchange .
fis:DerivativesExchange a owl:Class ; rdfs:subClassOf fis:Exchange .

fis:isTradedOn a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Exchange .
