@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "Ontology modelling securities, bonds, equities, derivatives and funds as described in the supplied corpus (general finance texts, US SEC/UK FCA material, IAS32/IFRS9, ECB glossary, BIS, OpenStax, FINRA, CFI)." .

#################################################################
# TOP-LEVEL FINANCIAL INSTRUMENT TAXONOMY
#################################################################

fis:FinancialInstrument a owl:Class ;
  rdfs:label "financial instrument" ;
  rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled; IAS 32/39 define it as any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity." .

fis:FinancialAsset a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "financial asset" ;
  rdfs:comment "Any asset that is cash, an equity instrument of another entity, a contractual right to receive cash or another financial instrument, or a contractual right to exchange financial instruments under potentially favourable conditions (IAS 32)." .

fis:FinancialLiability a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "financial liability" .

fis:CompoundFinancialInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "compound financial instrument" ;
  rdfs:comment "An instrument, such as a convertible bond, whose component parts (a liability component and an equity component) must be classified and presented separately under IAS 32." .

fis:DebtInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "debt instrument" .

fis:EquityInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "equity instrument" ;
  rdfs:comment "Any contract that evidences a residual interest in the assets of an entity after deducting all of its liabilities (IAS 32)." .

fis:DerivativeInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "derivative" ;
  rdfs:comment "Derivatives are one of three main categories of financial instrument, the other two being equity and debt. NOTE: the US SEC classifies derivatives as a category of 'security', while the UK FCA Handbook definition of 'security' excludes most derivatives; this conflict is preserved by not subclassing DerivativeInstrument under Security." ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( fis:FinancialInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Underlier ]
      [ a owl:Restriction ; owl:onProperty fis:requiresNoOrSmallInitialNetInvestment ; owl:hasValue true ]
      [ a owl:Restriction ; owl:onProperty fis:hasSettlementDate ; owl:someValuesFrom xsd:date ]
    )
  ] .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "cash instrument" ;
  rdfs:comment "Instruments whose value is determined directly by the markets; they can be securities (readily transferable) or instruments such as loans and deposits, where both parties must agree to any transfer." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:DebtInstrument fis:EquityInstrument fis:DerivativeInstrument ) .

fis:CashInstrument owl:disjointWith fis:DerivativeInstrument .

#################################################################
# SECURITY AND ITS STRUCTURAL CLASSIFICATIONS
#################################################################

fis:Security a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "security" ;
  rdfs:comment "A tradable financial asset; a financial contract which entitles the holder to investment returns, enforceable by law against the issuer." .

fis:DebtSecurity a owl:Class ;
  rdfs:label "debt security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security fis:DebtInstrument ) ] .

fis:EquitySecurity a owl:Class ;
  rdfs:label "equity security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security fis:EquityInstrument ) ] .

fis:HybridSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "hybrid security" ;
  rdfs:comment "Combines characteristics of both debt and equity securities (e.g. preferred stock, convertible bonds). Not asserted disjoint with DebtSecurity/EquitySecurity because the corpus explicitly describes overlap." .

fis:RegistrationForm a owl:Class ; rdfs:label "registration form" .
fis:BearerForm a owl:Class ; rdfs:subClassOf fis:RegistrationForm .
fis:RegisteredForm a owl:Class ; rdfs:subClassOf fis:RegistrationForm .
fis:BookEntryForm a owl:Class ; rdfs:subClassOf fis:RegistrationForm .
[] a owl:AllDisjointClasses ; owl:members ( fis:BearerForm fis:RegisteredForm fis:BookEntryForm ) .

fis:CertificatedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Represented by a physical certificate; may be bearer or registered." .
fis:NonCertificatedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Non-certificated, electronic (dematerialised) or 'book entry only' security." .
fis:CertificatedSecurity owl:disjointWith fis:NonCertificatedSecurity .

fis:BearerSecurity a owl:Class ; rdfs:subClassOf fis:CertificatedSecurity ;
  rdfs:label "bearer security" ;
  rdfs:comment "Entitles the holder to rights merely by holding the security; transferred by delivery." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:someValuesFrom fis:BearerForm ] ) ] .

fis:RegisteredSecurity a owl:Class ; rdfs:subClassOf fis:CertificatedSecurity ;
  rdfs:label "registered security" ;
  rdfs:comment "Entitles the holder to rights only if registered on a security register." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:someValuesFrom fis:RegisteredForm ] ) ] .

fis:BearerSecurity owl:disjointWith fis:RegisteredSecurity .

fis:DividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Each divided security constitutes a separate asset, legally distinct from every other security in the same issue." .
fis:UndividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "The entire issue makes up one single asset; each security is a fractional part of this whole." .
fis:DividedSecurity owl:disjointWith fis:UndividedSecurity .

fis:FungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "All holdings of the security are treated identically and are interchangeable." .
fis:NonFungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security .
fis:FungibleSecurity owl:disjointWith fis:NonFungibleSecurity .

#################################################################
# SUPPORTING CLASSES: ISSUERS, HOLDERS, COLLATERAL, EXCHANGES
#################################################################

fis:Issuer a owl:Class ;
  rdfs:label "issuer" ;
  rdfs:comment "The entity which is obligated on a security or other financial instrument." .

fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Municipality a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:InvestmentFund a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:comment "An investment fund that pools money from many investors and issues shares or units to them." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:SovereignGovernment fis:Municipality fis:Corporation fis:SupranationalOrganization fis:InvestmentFund ) .

fis:Holder a owl:Class ; rdfs:label "holder" .
fis:Shareholder a owl:Class ; rdfs:subClassOf fis:Holder ;
  rdfs:comment "An individual or company that legally owns one or more shares of stock." .
fis:Bondholder a owl:Class ; rdfs:subClassOf fis:Holder ;
  rdfs:comment "The creditor to whom the issuer of a bond owes principal and interest." .
fis:Shareholder owl:disjointWith fis:Bondholder .

fis:Collateral a owl:Class ; rdfs:label "collateral" .
fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Collateral .
fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:ResidentialMortgage owl:disjointWith fis:CommercialMortgage .

fis:Exchange a owl:Class ; rdfs:label "exchange" .
fis:StockExchange a owl:Class ; rdfs:subClassOf fis:Exchange ;
  rdfs:comment "An organized and officially recognized market on which securities can be bought and sold." .
fis:DerivativesExchange a owl:Class ; rdfs:subClassOf fis:Exchange ;
  rdfs:comment "A market where individuals trade standardized derivative contracts defined by the exchange." .

fis:Underlier a owl:Class ;
  rdfs:label "underlying asset" ;
  rdfs:comment "The asset (financial instrument, security, commodity, index, rate, currency or factual event) upon which a derivative contract is based." .

fis:Dividend a owl:Class ;
  rdfs:label "dividend" ;
  rdfs:comment "A discretionary portion of a company's profit paid to shareholders; unlike a bond coupon it is not a contractual obligation." .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Issuer ;
  rdfs:label "has issuer" .

fis:isIssuerOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ; rdfs:range fis:Security ;
  rdfs:label "is issuer of" .

fis:hasUnderlying a owl:ObjectProperty ;
  rdfs:domain fis:DerivativeInstrument ; rdfs:range fis:Underlier ;
  rdfs:label "has underlying" .

fis:isUnderlyingOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:Underlier ; rdfs:range fis:DerivativeInstrument ;
  rdfs:label "is underlying of" .

fis:hasHolder a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Holder ;
  rdfs:label "has holder" .

fis:isHolderOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasHolder ;
  rdfs:domain fis:Holder ; rdfs:range fis:Security ;
  rdfs:label "is holder of" .

fis:hasCreditRating a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range fis:CreditRatingCategory ;
  rdfs:label "has credit rating" .

fis:hasRepaymentSource a owl:ObjectProperty ;
  rdfs:domain fis:MunicipalBond ; rdfs:range fis:RevenueSource ;
  rdfs:label "has repayment source" .

fis:hasDividend a owl:ObjectProperty ;
  rdfs:domain fis:EquitySecurity ; rdfs:range fis:Dividend ;
  rdfs:label "has dividend" .

fis:hasReferenceEntity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:CreditDefaultSwap ; rdfs:range fis:Issuer ;
  rdfs:label "has reference entity" .

fis:hasRegistrationForm a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:RegistrationForm ;
  rdfs:label "has registration form" .

fis:hasRightType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range fis:TransactionRight ;
  rdfs:label "has right type" .

fis:hasStandardizationType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DerivativeInstrument ; rdfs:range fis:ContractStandardization ;
  rdfs:label "has standardization type" .

fis:isTradedOn a owl:ObjectProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:Exchange ;
  rdfs:label "is traded on" .

fis:hasCollateral a owl:ObjectProperty ;
  rdfs:domain fis:Bond ; rdfs:range fis:Collateral ;
  rdfs:label "has collateral" .

fis:hasLiabilityComponent a owl:ObjectProperty ;
  rdfs:domain fis:CompoundFinancialInstrument ; rdfs:range fis:FinancialLiability ;
  rdfs:label "has liability component" .

fis:hasEquityComponent a owl:ObjectProperty ;
  rdfs:domain fis:CompoundFinancialInstrument ; rdfs:range fis:EquityInstrument ;
  rdfs:label "has equity component" .

fis:hasBusinessModel a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialAsset ; rdfs:range fis:BusinessModel ;
  rdfs:label "has business model" .

fis:hasMeasurementCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialAsset ; rdfs:range fis:MeasurementCategory ;
  rdfs:label "has measurement category" .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:date ;
  rdfs:label "has maturity date" .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal ;
  rdfs:label "has face value" ;
  rdfs:comment "Nominal, principal, par or face amount; the amount on which interest is paid and which is repaid at maturity." .

fis:hasCouponRate a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal ;
  rdfs:label "has coupon rate" .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal ;
  rdfs:label "has strike price" .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:date ;
  rdfs:label "has expiration date" .

fis:hasPremium a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal ;
  rdfs:label "has premium" .

fis:hasNotionalAmount a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Swap ; rdfs:range xsd:decimal ;
  rdfs:label "has notional amount" .

fis:hasDeliveryDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Forward ; rdfs:range xsd:date ;
  rdfs:label "has delivery date" .

fis:hasConversionRatio a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:ConvertibleBond ; rdfs:range xsd:decimal ;
  rdfs:label "has conversion ratio" .

fis:hasCallPrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:CallableBond ; rdfs:range xsd:decimal ;
  rdfs:label "has call price" .

fis:requiresNoOrSmallInitialNetInvestment a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DerivativeInstrument ; rdfs:range xsd:boolean ;
  rdfs:label "requires no or small initial net investment" .

fis:hasSettlementDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DerivativeInstrument ; rdfs:range xsd:date ;
  rdfs:label "has settlement date" .

fis:hasContractualObligationToDeliverCash a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range xsd:boolean ;
  rdfs:label "has contractual obligation to deliver cash" .

fis:passesSolelyPaymentsOfPrincipalAndInterestTest a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialAsset ; rdfs:range xsd:boolean ;
  rdfs:label "passes SPPI test" .

#################################################################
# IAS 32 / IFRS 9 ACCOUNTING CLASSIFICATION (overlay on FinancialInstrument)
#################################################################

fis:FinancialLiability owl:equivalentClass [ a owl:Class ;
  owl:intersectionOf ( fis:FinancialInstrument
    [ a owl:Restriction ; owl:onProperty fis:hasContractualObligationToDeliverCash ; owl:hasValue true ] ) ] .

fis:EquityInstrument owl:equivalentClass [ a owl:Class ;
  owl:intersectionOf ( fis:FinancialInstrument
    [ a owl:Restriction ; owl:onProperty fis:hasContractualObligationToDeliverCash ; owl:hasValue false ] ) ] .

fis:MeasurementCategory a owl:Class ; rdfs:label "measurement category" .
fis:AmortisedCost a owl:Class ; rdfs:subClassOf fis:MeasurementCategory .
fis:FairValueThroughOCI a owl:Class ; rdfs:subClassOf fis:MeasurementCategory .
fis:FairValueThroughProfitOrLoss a owl:Class ; rdfs:subClassOf fis:MeasurementCategory .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:AmortisedCost fis:FairValueThroughOCI fis:FairValueThroughProfitOrLoss ) .

fis:BusinessModel a owl:Class ; rdfs:label "business model" .
fis:HoldToCollectBusinessModel a owl:Class ; rdfs:subClassOf fis:BusinessModel .
fis:HoldToCollectAndSellBusinessModel a owl:Class ; rdfs:subClassOf fis:BusinessModel .
fis:OtherBusinessModel a owl:Class ; rdfs:subClassOf fis:BusinessModel .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:HoldToCollectBusinessModel fis:HoldToCollectAndSellBusinessModel fis:OtherBusinessModel ) .

fis:AmortisedCostFinancialAsset a owl:Class ;
  rdfs:subClassOf fis:FinancialAsset ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialAsset
      [ a owl:Restriction ; owl:onProperty fis:hasBusinessModel ; owl:someValuesFrom fis:HoldToCollectBusinessModel ]
      [ a owl:Restriction ; owl:onProperty fis:passesSolelyPaymentsOfPrincipalAndInterestTest ; owl:hasValue true ] ) ] .

#################################################################
# DEBT SECURITY FAMILY
#################################################################

fis:Bond a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "bond" ;
  rdfs:comment "A type of security under which the issuer owes the holder a debt and is obliged to repay principal at maturity, usually together with interest (the coupon)." .

fis:Debenture a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "debenture" ;
  rdfs:comment "An unsecured bond, backed only by the general creditworthiness of the issuer." .

fis:Note a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "A debt security typically of shorter maturity than a debenture." .

fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument ;
  rdfs:comment "Conflict in corpus: one passage lists 'deposits' as a named form of debt security, while another explicitly distinguishes deposits/loans from securities because transfer requires mutual agreement rather than being readily transferable. Modelled here as a non-security CashInstrument; see CertificateOfDeposit for the negotiable, security-like form." .

fis:MoneyMarketInstrument a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Short-term debt instrument with original maturity of one year or less; highly liquid, sometimes called 'near cash'." .

fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:DebtSecurity, fis:MoneyMarketInstrument ;
  rdfs:comment "An unsecured promissory note with a fixed maturity usually less than 270 days." .

fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "A time deposit sold by banks, thrift institutions and credit unions, with a specific fixed term." .

fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Short-term loan arranged by selling securities with an agreement to repurchase them at a fixed price on a fixed date." .

fis:TreasuryBill a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:CommercialPaper fis:CertificateOfDeposit fis:TreasuryBill fis:BankersAcceptance fis:RepurchaseAgreement ) .

#################################################################
# BOND CLASSIFICATION BY ISSUER
#################################################################

fis:RevenueSource a owl:Class ; rdfs:label "revenue source" .
fis:TaxingPower a owl:Class ; rdfs:subClassOf fis:RevenueSource .
fis:SpecifiedRevenueStream a owl:Class ; rdfs:subClassOf fis:RevenueSource .
fis:PropertyAssessment a owl:Class ; rdfs:subClassOf fis:RevenueSource .
[] a owl:AllDisjointClasses ; owl:members ( fis:TaxingPower fis:SpecifiedRevenueStream fis:PropertyAssessment ) .

fis:GovernmentBond a owl:Class ;
  rdfs:label "government bond" ; rdfs:comment "Also called sovereign bond or treasury bond; issued by a sovereign national government." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] .

fis:MunicipalBond a owl:Class ;
  rdfs:label "municipal bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Municipality ] ) ] .

fis:CorporateBond a owl:Class ;
  rdfs:label "corporate bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

fis:SupranationalBond a owl:Class ;
  rdfs:label "supranational bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:GovernmentBond fis:MunicipalBond fis:CorporateBond fis:SupranationalBond ) .

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "A bond issued by a government to fund military operations during wartime." .

fis:TreasuryNote a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "US Treasury security with maturity of two, three, five or ten years." .
fis:TreasuryBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "US Treasury security with the longest maturity, from twenty to thirty years (T-bond / long bond)." .
fis:TreasuryInflationProtectedSecurity a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "TIPS: principal adjusted to the Consumer Price Index." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:TreasuryBill fis:TreasuryNote fis:TreasuryBond fis:TreasuryInflationProtectedSecurity ) .

fis:ConventionalGilt a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "UK gilt with fixed interest rate and length." .
fis:IndexLinkedGilt a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "UK gilt whose interest rate and principal are automatically adjusted for inflation." .
fis:ConventionalGilt owl:disjointWith fis:IndexLinkedGilt .

fis:GeneralObligationBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MunicipalBond
      [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:TaxingPower ] ) ] .

fis:RevenueBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MunicipalBond
      [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:SpecifiedRevenueStream ] ) ] ;
  rdfs:comment "Repayment guaranteed solely from revenues generated by a specified revenue-generating entity; typically non-recourse." .

fis:AssessmentBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MunicipalBond
      [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:PropertyAssessment ] ) ] .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:GeneralObligationBond fis:RevenueBond fis:AssessmentBond ) .

fis:CreditRatingCategory a owl:Class ; rdfs:label "credit rating category" .
fis:InvestmentGradeRating a owl:Class ; rdfs:subClassOf fis:CreditRatingCategory .
fis:HighYieldRating a owl:Class ; rdfs:subClassOf fis:CreditRatingCategory .
fis:InvestmentGradeRating owl:disjointWith fis:HighYieldRating .

fis:InvestmentGradeBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:CorporateBond
      [ a owl:Restriction ; owl:onProperty fis:hasCreditRating ; owl:someValuesFrom fis:InvestmentGradeRating ] ) ] .

fis:HighYieldBond a owl:Class ;
  rdfs:comment "Also called junk bond; rated below investment grade." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:CorporateBond
      [ a owl:Restriction ; owl:onProperty fis:hasCreditRating ; owl:someValuesFrom fis:HighYieldRating ] ) ] .

fis:InvestmentGradeBond owl:disjointWith fis:HighYieldBond .

#################################################################
# BOND CLASSIFICATION BY MATURITY
#################################################################

fis:ShortTermBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:MediumTermBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:LongTermBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Also called a perpetuity; has no maturity date." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:ShortTermBond fis:MediumTermBond fis:LongTermBond fis:PerpetualBond ) .

#################################################################
# BOND CLASSIFICATION BY COUPON TYPE
#################################################################

fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon remains constant throughout the life of the bond." .
fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon varies, linked to a reference rate such as LIBOR/SOFR or Euribor." .
fis:ZeroCouponBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Pays no periodic interest; issued at a deep discount and repaid at par at maturity." .
fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Principal and interest payments indexed to the level of consumer prices." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond fis:InflationIndexedBond ) .

fis:StepUpBond a owl:Class ; rdfs:subClassOf fis:FixedRateBond ;
  rdfs:comment "Stepped-coupon bond whose coupon increases during the life of the bond." .

fis:TreasuryInflationProtectedSecurity rdfs:subClassOf fis:InflationIndexedBond .
fis:IndexLinkedGilt rdfs:subClassOf fis:InflationIndexedBond .
fis:ConventionalGilt rdfs:subClassOf fis:FixedRateBond .
fis:TreasuryBill rdfs:subClassOf fis:ZeroCouponBond .

#################################################################
# BOND CLASSIFICATION BY EMBEDDED OPTION
#################################################################

fis:CallableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issuer has the right to repay the bond before maturity on call dates." .
fis:PutableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Holder has the right to force repayment before maturity on put dates (retractable bond)." .
fis:BulletBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A straight bond that is neither callable nor putable." .

fis:BulletBond owl:disjointWith fis:CallableBond .
fis:BulletBond owl:disjointWith fis:PutableBond .

#################################################################
# BOND REGISTRATION FORM
#################################################################

fis:BearerBond a owl:Class ;
  rdfs:comment "An official certificate issued without a named holder; claimable by whoever possesses it." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:someValuesFrom fis:BearerForm ] ) ] .

fis:RegisteredBond a owl:Class ;
  rdfs:comment "Ownership recorded by the issuer or transfer agent; the opposite of a bearer bond." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:someValuesFrom fis:RegisteredForm ] ) ] .

fis:BookEntryBond a owl:Class ;
  rdfs:comment "A bond that does not have a paper certificate." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:someValuesFrom fis:BookEntryForm ] ) ] .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:BearerBond fis:RegisteredBond fis:BookEntryBond ) .

#################################################################
# BOND SENIORITY AND SECURITY (COLLATERAL)
#################################################################

fis:SecuredBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Collateral ] ) ] .
fis:SecuredBond owl:disjointWith fis:Debenture .

fis:SeniorBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Contractually senior to other unsecured debt; priority in bankruptcy." .
fis:SubordinatedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Lower priority than senior bonds of the same issuer in liquidation." .
fis:SeniorBond owl:disjointWith fis:SubordinatedBond .

#################################################################
# ASSET-BACKED / MORTGAGE-BACKED SECURITY FAMILY
#################################################################

fis:AssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Bond backed by a pool of assets such as consumer loans, leases or receivables; interest and principal payments backed by underlying cash flows." .

fis:MortgageBackedSecurity a owl:Class ;
  rdfs:label "mortgage-backed security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] ) ] .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] .

fis:CommercialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CommercialMortgage ] ) ] .

fis:ResidentialMortgageBackedSecurity owl:disjointWith fis:CommercialMortgageBackedSecurity .

fis:CollateralizedDebtObligation a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ;
  rdfs:comment "Structured asset-backed security sliced into tranches catching cash flow by seniority." .
fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "Pay-through bond; debt obligation of a legal entity collateralized by the mortgage assets it owns, divided into tranches." .
fis:PassThroughSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "Interest and principal payments pass through from the borrower to the holder on a pro rata basis." .
fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity .
fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
  rdfs:comment "Cash flows backed by the interest component of mortgage payments." .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
  rdfs:comment "Cash flows backed by the principal-repayment component of mortgage payments." .
fis:InterestOnlyStrip owl:disjointWith fis:PrincipalOnlyStrip .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Backed by cash flows from mortgages or public sector assets, which remain on the issuer's balance sheet (unlike asset-backed securities)." .
fis:CoveredBond owl:disjointWith fis:AssetBackedSecurity .

#################################################################
# HYBRID SECURITIES
#################################################################

fis:PreferredStock a owl:Class ; rdfs:subClassOf fis:HybridSecurity ;
  rdfs:label "preferred stock" ;
  rdfs:comment "Also called preference shares; an intermediate class of security between equity and debt, legally a capital stock, generally without voting rights but senior to common stock for dividends and liquidation. NOTE: under IAS 32, a mandatorily redeemable preference share is classified as a FinancialLiability rather than equity, which conflicts with the common description of preferred stock as a capital stock / equity instrument; both views are preserved in the corpus." .

fis:CumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Unpaid dividends accumulate and must be paid before common dividends resume." .
fis:NoncumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "A missed dividend is simply lost, not accumulated." .
fis:CumulativePreferredStock owl:disjointWith fis:NoncumulativePreferredStock .

fis:ConvertibleBond a owl:Class ; rdfs:subClassOf fis:HybridSecurity, fis:CompoundFinancialInstrument ;
  rdfs:label "convertible bond" ;
  rdfs:comment "A bond the holder can convert into a specified number of shares of the issuer's common stock." .

fis:MandatoryConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Forces the holder to convert into shares at maturity." .
fis:ContingentConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Automatically converted into equity if a pre-specified trigger event occurs (CoCo)." .

fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:HybridSecurity ;
  rdfs:comment "Allows exchange into shares of a corporation other than the issuer." .

fis:EquityWarrant a owl:Class ; rdfs:subClassOf fis:HybridSecurity, fis:Option ;
  rdfs:comment "An option issued by a company allowing the holder to purchase a specific number of shares at a specified price within a specified time." .

#################################################################
# EQUITY SECURITIES
#################################################################

fis:CommonStock a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
  rdfs:label "common stock" ;
  rdfs:comment "A form of corporate equity ownership typically carrying voting rights and residual claims on profits and assets." .

fis:CommonStock owl:disjointWith fis:PreferredStock .

fis:DepositaryReceipt a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
  rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities." .
fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:comment "Listed and traded in the United States." .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:comment "Issued by European banks." .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) .

#################################################################
# DERIVATIVE INSTRUMENTS
#################################################################

fis:Forward a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:label "forward" ;
  rdfs:comment "A non-standardized contract between two parties to buy or sell an asset at a specified future time at an agreed price." .

fis:Future a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:label "future" ;
  rdfs:comment "A standardized contract, written by a clearing house, to buy or sell an asset on a future date at a price agreed today." .

fis:Option a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:label "option" ;
  rdfs:comment "Grants the holder the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DerivativeInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasStrikePrice ; owl:someValuesFrom xsd:decimal ]
      [ a owl:Restriction ; owl:onProperty fis:hasExpirationDate ; owl:someValuesFrom xsd:date ] ) ] .

fis:Swap a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:label "swap" ;
  rdfs:comment "A derivative in which two counterparties exchange cash flows of one party's financial instrument for those of the other's." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:Forward fis:Future fis:Option fis:Swap ) .

fis:ContractStandardization a owl:Class ; rdfs:label "contract standardization" .
fis:StandardizedContract a owl:Class ; rdfs:subClassOf fis:ContractStandardization .
fis:NonStandardizedContract a owl:Class ; rdfs:subClassOf fis:ContractStandardization .
fis:StandardizedContract owl:disjointWith fis:NonStandardizedContract .

fis:Future owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DerivativeInstrument
    [ a owl:Restriction ; owl:onProperty fis:hasStandardizationType ; owl:someValuesFrom fis:StandardizedContract ] ) ] .

fis:Forward owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DerivativeInstrument
    [ a owl:Restriction ; owl:onProperty fis:hasStandardizationType ; owl:someValuesFrom fis:NonStandardizedContract ] ) ] .

fis:TransactionRight a owl:Class ; rdfs:label "transaction right" .
fis:RightToBuy a owl:Class ; rdfs:subClassOf fis:TransactionRight .
fis:RightToSell a owl:Class ; rdfs:subClassOf fis:TransactionRight .
fis:RightToBuy owl:disjointWith fis:RightToSell .

fis:CallOption a owl:Class ;
  rdfs:comment "The right, but not the obligation, to buy an asset at a fixed price." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasRightType ; owl:someValuesFrom fis:RightToBuy ] ) ] .

fis:PutOption a owl:Class ;
  rdfs:comment "The right, but not the obligation, to sell an asset at a fixed price." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasRightType ; owl:someValuesFrom fis:RightToSell ] ) ] .

fis:CallOption owl:disjointWith fis:PutOption .

fis:AmericanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "May be exercised on any trading day on or before expiration." .
fis:EuropeanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "May only be exercised on expiry." .
fis:BermudanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "May be exercised only on specified dates on or before expiration." .
fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Payoff determined by the average underlying price over a preset period." .
fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "The underlying price must pass a certain barrier before it can be exercised." .
fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "An all-or-nothing option paying the full amount if a defined condition is met at expiration." .
fis:ExoticOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "A broad category of options with complex financial structures." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption fis:AsianOption fis:BarrierOption fis:BinaryOption ) .

fis:ExchangeTradedOption a owl:Class ; rdfs:subClassOf fis:Option .
fis:OverTheCounterOption a owl:Class ; rdfs:subClassOf fis:Option .
fis:ExchangeTradedOption owl:disjointWith fis:OverTheCounterOption .

fis:ExchangeTradedDerivative a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:comment "Traded via specialized derivatives exchanges or other exchanges." .
fis:OverTheCounterDerivative a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:comment "Privately negotiated directly between two parties without going through an exchange." .
fis:ExchangeTradedDerivative owl:disjointWith fis:OverTheCounterDerivative .

fis:LockProduct a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:comment "Obligates the contractual parties to the terms over the life of the contract (e.g. swaps, futures, forwards)." .
fis:OptionProduct a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:comment "Provides the buyer the right, but not the obligation, to enter the contract under specified terms." .
fis:LockProduct owl:disjointWith fis:OptionProduct .

fis:Forward rdfs:subClassOf fis:LockProduct .
fis:Future rdfs:subClassOf fis:LockProduct .
fis:Swap rdfs:subClassOf fis:LockProduct .
fis:Option rdfs:subClassOf fis:OptionProduct .

fis:StockOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:StockFuture a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Future
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CreditDefaultSwap a owl:Class ; rdfs:subClassOf fis:Swap ;
  rdfs:label "credit default swap" ;
  rdfs:comment "Seller compensates the buyer in the event of a loan default or other credit event on the reference entity." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:Issuer ] ) ] .
fis:CommoditySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:EquitySwap a owl:Class ; rdfs:subClassOf fis:Swap .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap fis:CommoditySwap fis:EquitySwap ) .

#################################################################
# INVESTMENT FUNDS
#################################################################

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "mutual fund" ;
  rdfs:comment "An SEC-registered open-end investment company that pools money from many investors to purchase securities." .

fis:OpenEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
  rdfs:comment "Purchased from or sold to the issuer at net asset value." .
fis:ClosedEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:UnitInvestmentTrust a owl:Class ; rdfs:subClassOf fis:MutualFund .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:OpenEndFund fis:ClosedEndFund fis:UnitInvestmentTrust ) .

fis:MoneyMarketFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:BondFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:EquityFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:HybridFund a owl:Class ; rdfs:subClassOf fis:MutualFund .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:MoneyMarketFund fis:BondFund fis:EquityFund fis:HybridFund ) .

fis:IndexFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Passively managed fund that tracks the performance of an index." .
fis:ActivelyManagedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Seeks to outperform market indices; generally charges higher fees." .
fis:IndexFund owl:disjointWith fis:ActivelyManagedFund .

fis:ExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "exchange-traded fund" ;
  rdfs:comment "Must register as an open-end investment company or unit investment trust, but shares trade on national securities exchanges at market prices that may differ from net asset value." .
fis:ExchangeTradedFund owl:disjointWith fis:MutualFund .

fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Pools money like a mutual fund but has far fewer investor-protection regulations and is available mainly to high-net-worth individuals." .
fis:HedgeFund owl:disjointWith fis:MutualFund .
fis:HedgeFund owl:disjointWith fis:ExchangeTradedFund .

